const input = Array.isArray($json) ? $json : [$json];
const lostReasons = ['price', 'timing', 'competitor', 'no-response', 'scope'];
return input.map((deal) => {
  const quoteAgeDays = Number(deal.quoteAgeDays ?? 0);
  const estimateValue = Number(deal.estimateValue ?? 0);
  const type = `${deal.estimateType ?? ''}`.toLowerCase();
  const jobFamily = type.includes('repipe')
    ? 'repipe'
    : type.includes('water heater') || type.includes('tankless')
      ? 'water-heater'
      : type.includes('sewer')
        ? 'sewer'
        : 'fixture';
  const lostReason = lostReasons.includes(deal.lostReason) ? deal.lostReason : null;
  const cadence = lostReason
    ? 'closed-lost'
    : quoteAgeDays >= 14
      ? 'manager-review'
      : quoteAgeDays >= 5
        ? 'follow-up-now'
        : 'wait';
  const financeReminderEligible = estimateValue >= 5000;
  const messageTheme = financeReminderEligible ? `${jobFamily}-value-and-finance-options` : `${jobFamily}-scope-and-schedule`;
  const nextAction = cadence === 'closed-lost'
    ? `Tag lost reason (${lostReason}) and feed the owner report.`
    : cadence === 'wait'
      ? 'No message today.'
      : 'Send approved estimate follow-up.';
  return { json: { ...deal, jobFamily, lostReason, cadence, financeReminderEligible, messageTheme, nextAction } };
});
